    (95, 'c', 'supermaven', ARRAY['metrics', 'news_mentions']::text[], 'set', 'news_mentions', true, NULL::jsonb, NULL::jsonb, 'news_mentions_12m', 'https://aipowerranking.com/api/news', '2026-10-27', NULL::text, NULL::text[], NULL::jsonb),
